18	// DocumentAt returns the top-level mapping of the document that holds line.
19	func DocumentAt(content []byte, line int) (*yaml.Node, bool) {
20		dec := yaml.NewDecoder(bytes.NewReader(content))
21		for {
22			var doc yaml.Node
23			err := dec.Decode(&doc)
24			if errors.Is(err, io.EOF) || err != nil {
25				return nil, false
26			}
27			if doc.Kind != yaml.DocumentNode || len(doc.Content) == 0 {
28				continue
29			}
30			root := doc.Content[0]
31			if root.Kind == yaml.MappingNode && root.Line <= line && line <= lastLine(root) {
32				return root, true
33			}
34		}
35	}
