37	// Containers returns every container mapping of a workload, wherever its pod
38	// template sits — spec.containers for a Pod, spec.template.spec for a
39	// Deployment, spec.jobTemplate.spec.template.spec for a CronJob — along with
40	// init and ephemeral containers.
41	func Containers(doc *yaml.Node) []*yaml.Node {
42		var out []*yaml.Node
43		var walk func(n *yaml.Node)
44		walk = func(n *yaml.Node) {
45			n = resolveAlias(n)
46			if n.Kind != yaml.MappingNode {
47				return
48			}
49			for i := 0; i+1 < len(n.Content); i += 2 {
50				key, value := n.Content[i].Value, resolveAlias(n.Content[i+1])
51				if (key == "containers" || key == "initContainers" || key == "ephemeralContainers") && value.Kind == yaml.SequenceNode {
52					for _, c := range value.Content {
53						if c = resolveAlias(c); c.Kind == yaml.MappingNode {
54							out = append(out, c)
55						}
56					}
57					continue
58				}
59				walk(value)
60			}
61		}
62		walk(doc)
63		return out
64	}
65	
66	// Entry returns the key and value nodes of one key of a mapping.
67	func Entry(m *yaml.Node, key string) (*yaml.Node, *yaml.Node, bool) {
68		m = resolveAlias(m)
69		if m.Kind != yaml.MappingNode {
70			return nil, nil, false
71		}
72		k, v, ok := mappingEntry(m, key)
73		if ok {
74			v = resolveAlias(v)
75		}
76		return k, v, ok
77	}
