// decode error, keeping the documents read before it, and ignores documents
// that are not a mapping.
func IndexDocuments(content []byte) *DocumentIndex {
	index := &DocumentIndex{}
	dec := yaml.NewDecoder(bytes.NewReader(content))
	for {
